startAgainstNpc.example:
// A tavern gambler: a hard opponent for a bet of 50 groschen.
const { Events, Chat } = kcds.core;
const bets = new Map();

Events.on('playerCommand', (player, command) => {
  if (command !== 'gamble') {
    return;
  }
  const match = kcds.world.Dice.startAgainstNpc(player, {
    difficulty: 'hard',
    npcName: 'Gambler',
    targetScore: 1500,
  });
  bets.set(match, { player, stake: 50 });
});

Events.on('diceMatchEnd', (match, first, second, winner) => {
  const bet = bets.get(match);
  if (!bet) {
    return;
  }
  if ([first, second][winner] === bet.player) {
    Chat.sendToPlayer(bet.player, `You win ${bet.stake * 2} groschen.`);
  }
  bets.delete(match);
});

startAgainstNpc.exampleCs:
// A tavern gambler: a hard opponent for a bet of 50 groschen.
var bets = new Dictionary<double, (Player player, int stake)>();

Events.On("playerCommand", (Player player, string command) =>
{
    if (command != "gamble")
    {
        return;
    }
    var match = Dice.StartAgainstNpc(player, new
    {
        difficulty = "hard",
        npcName = "Gambler",
        targetScore = 1500,
    });
    bets[match] = (player, 50);
});

Events.On("diceMatchEnd", (double match, JsValue first, JsValue second, int winner) =>
{
    if (!bets.Remove(match, out var bet))
    {
        return;
    }
    // winner is 0 for the first seat, 1 for the second
    var seat = winner == 0 ? first : second;
    if (seat.Is(bet.player.AsValue()))
    {
        Chat.SendToPlayer(bet.player, $"You win {bet.stake * 2} groschen.");
    }
});

sit.example:
const { Dice } = kcds.world;

kcds.core.Events.on('diceTableUse', (player, table, match) => {
  if (match === 0 && Dice.sit(player.id) < 0) {
    kcds.core.Chat.sendToPlayer(player, 'Both chairs are taken.');
  }
});

